const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))
const flag = n => ({Argentina:'🇦🇷',Brasil:'🇧🇷',Chile:'🇨🇱',Colômbia:'🇨🇴',Equador:'🇪🇨',Paraguai:'🇵🇾',Uruguai:'🇺🇾',Venezuela:'🇻🇪'})[n] || '⚽'
const teamName = id => state.teams.find(t => t.id === id)?.name || '—'
const playerName = id => { const p=state.players.find(x=>x.id===id); return p ? (p.full_name||p.name||'—') : '—' }
const fmtDate = v => v ? new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}) : '—'
const canOperate = () => !!state.session && ['admin','organizador','arbitro','operador'].includes(state.profile?.role)
const roleLabel = r => ({admin:'Administrador',organizador:'Organizador',arbitro:'Árbitro',operador:'Operador',publico:'Público'})[r] || 'Público'

async function loadProfile(session){
  if(!session) return null
  const profileRes = await supabase.from('profiles').select('id,full_name,role,phone,created_at').eq('id', session.user.id).maybeSingle()
  if(profileRes.data) return profileRes.data
  const rpcRes = await supabase.rpc('get_my_profile')
  if(!rpcRes.error && Array.isArray(rpcRes.data) && rpcRes.data.length) return rpcRes.data[0]
  console.warn('Não foi possível carregar o perfil do usuário.', {
    userId: session.user.id,
    profileError: profileRes.error?.message || null,
    rpcError: rpcRes.error?.message || null
  })
  return null
}

async function load(){
  state.loading = true
  const sessionRes = await supabase.auth.getSession()
  state.session = sessionRes.data.session
  if(state.session){
    const userRes = await supabase.auth.getUser()
    if(userRes.error || !userRes.data.user){
      console.warn('Sessão inválida ou expirada.', userRes.error?.message || '')
      await supabase.auth.signOut()
      state.session = null
      state.profile = null
    } else {
      state.session = {...state.session, user:userRes.data.user}
      state.profile = await loadProfile(state.session)
    }
  } else state.profile = null
  const q = async t => (await supabase.from(t).select('*')).data || []
  state.competition = (await supabase.from('competitions').select('*').eq('name','2ª Copa das Nações Ouro/Prata/Diamante').maybeSingle()).data
  ;[state.matches,state.teams,state.players,state.referees,state.groups,state.sponsors,state.media,state.allEvents] = await Promise.all(['matches','teams','players','referees','groups','sponsors','media_files'].map(q).concat([supabase.from('match_events').select('*').order('created_at',{ascending:true}).then(r=>r.data||[])]))
  state.matches.sort((a,b)=>new Date(a.scheduled_at||0)-new Date(b.scheduled_at||0))
  if(state.selectedMatch) await loadMatchDetails(state.selectedMatch.id, false)
  state.loading = false
  render()
}

async function loadMatchDetails(id, doRender=true){
  if(state.selectedMatch?.id!==id){state.eventClockSeconds=0;state.eventTimerStartedAt=null;stopEventTicker();state.editingSubId=null}
  state.selectedMatch = state.matches.find(m=>String(m.id)===String(id)) || null
  if(!state.selectedMatch){
    const mr = await supabase.from('matches').select('*').eq('id',id).maybeSingle()
    state.selectedMatch = mr.data || null
    if(state.selectedMatch){
      const i=state.matches.findIndex(m=>String(m.id)===String(id))
      if(i>=0) state.matches[i]=state.selectedMatch; else state.matches.push(state.selectedMatch)
    }
  }
  if(!state.selectedMatch){ state.events=[]; state.lineups=[]; state.votes=[]; if(doRender) render(); return }
  const [ev,lu,v] = await Promise.all([
    supabase.from('match_events').select('*').eq('match_id',id).order('created_at',{ascending:true}),
    supabase.from('match_lineups').select('*').eq('match_id',id),
    supabase.from('match_votes').select('*').eq('match_id',id)
  ])
  state.events=ev.data||[]; state.lineups=lu.data||[]; state.votes=v.data||[]
  if(doRender) render()
}

function subscribe(){
  supabase.channel('futebol-campo-live')
    .on('postgres_changes',{event:'*',schema:'public',table:'matches'}, async payload=>{
      const i=state.matches.findIndex(x=>x.id===payload.new?.id)
      if(payload.eventType==='DELETE'){ if(i>=0) state.matches.splice(i,1) }
      else if(i>=0) state.matches[i]=payload.new; else state.matches.push(payload.new)
      if(state.selectedMatch?.id===payload.new?.id) await loadMatchDetails(payload.new.id,false)
      render()
    })
    .on('postgres_changes',{event:'*',schema:'public',table:'match_events'}, async payload=>{
      if(state.selectedMatch?.id===payload.new?.match_id) await loadMatchDetails(state.selectedMatch.id,false)
      render()
    })
    .on('postgres_changes',{event:'*',schema:'public',table:'match_lineups'}, async payload=>{
      if(state.selectedMatch?.id===payload.new?.match_id) await loadMatchDetails(state.selectedMatch.id,false)
      render()
    })
    .on('postgres_changes',{event:'*',schema:'public',table:'match_votes'}, async payload=>{
      if(state.selectedMatch?.id===payload.new?.match_id) await loadMatchDetails(state.selectedMatch.id,false)
      render()
    }).subscribe()
}

function nav(){return `<aside><div class="brand">⚽ <span>OURO & PRATA</span></div><nav>${[['dashboard','Painel','⌂'],['jogos','Jogos','▣'],['ao_vivo','Ao vivo','●'],['times','Times','◈'],['atletas','Atletas','♙'],['arbitragem','Arbitragem','⚑'],['grupos','Grupos','▦'],['classificacao','Classificação','☷'],['patrocinadores','Patrocinadores','★'],['midia','Fotos / Arquivos','▤'],['relatorios','Relatórios','▥']].map(x=>`<button class="${state.tab===x[0]?'active':''}" data-tab="${x[0]}"><i>${x[2]}</i><span>${x[1]}</span></button>`).join('')}</nav><div class="sidefoot">2ª Copa das Nações<br><small>Ouro • Prata • Diamante</small></div></aside>`}
function header(){return `<header><div><div class="eyebrow">GESTÃO ESPORTIVA • ONLINE</div><h1>${title()}</h1></div><div class="header-actions"><span class="pill">● ${state.session?'CONECTADO':'MODO PÚBLICO'}</span><button class="userbtn" id="authBtn">${state.session?`👤 ${esc(state.profile?.full_name||state.session.user.email)} · ${roleLabel(state.profile?.role)}`:'🔐 Entrar'}</button></div></header>`}
function title(){return ({dashboard:'Painel geral',jogos:'Jogos',ao_vivo:'Central ao vivo',times:'Times',atletas:'Atletas',arbitragem:'Arbitragem',grupos:'Classificação por grupo',classificacao:'Classificação geral',patrocinadores:'Patrocinadores',midia:'Fotos e arquivos',relatorios:'Relatórios'})[state.tab]}
function card(title,value,sub=''){return `<div class="card"><div class="muted">${title}</div><div class="big">${value}</div><div class="muted">${sub}</div></div>`}
function content(){
  if(state.tab==='dashboard') return `<section class="grid4">${card('Times',state.teams.length,'seleções cadastradas')}${card('Atletas',state.players.length,'cadastros')}${card('Árbitros',state.referees.length,'cadastros')}${card('Jogos',state.matches.length,'na competição')}</section><section class="panel hero"><div><span class="status">${state.competition?.status?.toUpperCase()||'ATIVA'}</span><h2>2ª Copa das Nações Ouro/Prata/Diamante</h2><p class="muted">Central profissional para jogos, súmulas, escalações, arbitragem, classificação e acompanhamento em tempo real.</p></div><div class="hero-score">${state.matches.filter(m=>m.status==='ao_vivo').length}<small>partidas ao vivo</small></div></section><section class="panel"><h2>Seleções</h2><div class="flags">${state.teams.map(t=>`<span>${flag(t.name)} ${esc(t.name)}</span>`).join('')}</div></section><section class="panel"><h2>Próximos jogos</h2>${matchesTable()}</section>`
  if(state.tab==='jogos') return gamesView()
  if(state.tab==='ao_vivo') return state.selectedMatch ? liveSheet() : `<section class="panel"><div class="panelhead"><div><h2>Central ao vivo</h2><p class="muted">Selecione uma partida em Jogos para abrir a súmula.</p></div></div>${matchesTable(true)}</section>`
  if(state.tab==='times') return list('Times',state.teams.map(t=>[flag(t.name)+' '+esc(t.name),t.country||'Seleção']), 'team')
  if(state.tab==='atletas') return list('Atletas',state.players.map(p=>[esc(p.full_name||p.name),(esc(teamName(p.team_id)))+' • '+esc(p.category||'')+' • '+esc(p.position||'')]), 'player')
  if(state.tab==='arbitragem') return list('Equipe de arbitragem',state.referees.map(r=>[esc(r.name),esc(r.registration||'Árbitro')]), 'referee')
  if(state.tab==='grupos') return groupStandingsView()
  if(state.tab==='classificacao') return classificationView('geral')
  if(state.tab==='patrocinadores') return sponsorsView()
  if(state.tab==='midia') return mediaView()
  if(state.tab==='relatorios') return reportsView()
}
function gamesView(){return `<section class="panel"><div class="panelhead"><div><h2>Calendário e partidas</h2><p class="muted">Partidas agendadas, em andamento e encerradas.</p></div>${canOperate()?'<button class="primary" data-crud="match">+ Novo jogo</button>':''}</div>${matchesTable(true)}</section>`}
function matchStatusLabel(status){return status==='agendado'?'PARTIDA NÃO INICIADA':status==='ao_vivo'?'AO VIVO':status==='encerrado'?'ENCERRADA':status.toUpperCase()}
function matchesTable(selectable=false){if(!state.matches.length)return `<div class="empty">Nenhum jogo cadastrado ainda.</div>`;return `<div class="tablewrap"><table><tr><th>Data</th><th>Jogo</th><th>Placar</th><th>Status</th>${selectable?'<th>Ações</th>':''}</tr>${state.matches.map(m=>{const h=teamName(m.home_team_id),a=teamName(m.away_team_id);const actions=selectable&&canOperate()?`${m.status==='encerrado'?`<button class="smallbtn" data-reopen-match="${m.id}">↩ Reabrir</button>`:`<button class="smallbtn" data-edit-crud="match" data-id="${m.id}">✏️ Alterar</button>`}${m.status!=='ao_vivo'?`<button class="smallbtn" data-not-started="${m.id}">⏳ Não iniciada</button>`:''}<button class="smallbtn" data-open-match="${m.id}">Abrir</button>`:'';return `<tr><td>${fmtDate(m.scheduled_at)}</td><td>${flag(h)} <b>${esc(h)}</b> × <b>${esc(a)}</b> ${flag(a)}</td><td><b>${m.home_score} × ${m.away_score}</b></td><td><span class="tag ${m.status}">${matchStatusLabel(m.status)}</span></td>${selectable?`<td>${actions}</td>`:''}</tr>`}).join('')}</table></div>`}
function calcStandings(teamIds=null){const rows=state.teams.filter(t=>!teamIds||teamIds.includes(t.id)).map(t=>({team:t,j:0,v:0,e:0,d:0,gp:0,gc:0,pts:0}));const map=new Map(rows.map(r=>[r.team.id,r]));state.matches.filter(m=>m.status==='encerrado').forEach(m=>{const h=map.get(m.home_team_id),a=map.get(m.away_team_id);if(!h||!a)return;h.j++;a.j++;h.gp+=m.home_score||0;h.gc+=m.away_score||0;a.gp+=m.away_score||0;a.gc+=m.home_score||0;if(m.home_score>m.away_score){h.v++;h.pts+=3;a.d++}else if(m.home_score<m.away_score){a.v++;a.pts+=3;h.d++}else{h.e++;a.e++;h.pts++;a.pts++}});return rows.sort((a,b)=>b.pts-a.pts||(b.gp-b.gc)-(a.gp-a.gc)||b.gp-a.gp||a.team.name.localeCompare(b.team.name))}
function standingsTable(rows){return `<div class="tablewrap"><table><tr><th>#</th><th>Equipe</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th><th>Pts</th></tr>${rows.map((r,i)=>`<tr><td><b>${i+1}</b></td><td>${flag(r.team.name)} ${esc(r.team.name)}</td><td>${r.j}</td><td>${r.v}</td><td>${r.e}</td><td>${r.d}</td><td>${r.gp}</td><td>${r.gc}</td><td>${r.gp-r.gc}</td><td><b>${r.pts}</b></td></tr>`).join('')}</table></div>`}
function classificationTabs(active){return `<div class="class-tabs"><button class="${active==='grupo'?'active':''}" data-classification="grupo">Classificação por grupo</button><button class="${active==='geral'?'active':''}" data-classification="geral">Classificação geral</button></div>`}
function groupStandingsView(){const groups=state.groups.slice().sort((a,b)=>a.position-b.position).filter(g=>g.position <= (state.competition?.group_count||2));return `<section class="panel"><div class="panelhead"><div><h2>Classificação por grupo</h2><p class="muted">Pontuação, confronto direto, saldo, gols marcados e gols sofridos.</p></div>${canOperate()?'<button class="primary" data-configure-competition>⚙️ Configurar grupos e fases</button>':''}</div>${classificationTabs('grupo')}${groups.map(g=>{const teams=state.teams.filter(t=>t.group_id===g.id);return `<div class="panel group-box"><h3>${esc(g.name)}</h3>${teams.length?standingsTable(calcStandings(teams.map(t=>t.id))):'<div class="empty">Nenhuma equipe neste grupo.</div>'}</div>`}).join('')}</section>`}
function classificationView(active='geral'){return active==='grupo'?groupStandingsView():standingsView()}
function openCompetitionConfig(){if(!canOperate())return;const c=state.competition||{}, phases=Array.isArray(c.phases)&&c.phases.length?c.phases:[{name:'Classificatória',type:'classificatoria'}];document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="competitionConfigModal"><div class="modalbox config-modal"><button class="close" data-close>×</button><div class="eyebrow">CAMPEONATO</div><h2>Configurar grupos e fases</h2><label>Quantidade de grupos<select id="cfgGroupCount">${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}" ${Number(c.group_count||2)===n?'selected':''}>${n}</option>`).join('')}</select></label><div class="phase-head"><b>Fases</b><button class="secondary" data-phase-add>+ Adicionar fase</button></div><div id="phaseList">${phases.map((p,i)=>phaseRow(p,i)).join('')}</div><div class="modal-actions"><button class="secondary" data-close>Cancelar</button><button class="primary" data-phase-save>Salvar configuração</button></div></div></div>`)}
function phaseRow(p,i){return `<div class="phase-row" data-phase-row><input data-phase-name value="${esc(p.name||'Fase '+(i+1))}" placeholder="Nome da fase"><select data-phase-type><option value="classificatoria" ${p.type==='classificatoria'?'selected':''}>Classificatória</option><option value="mata-mata" ${p.type==='mata-mata'?'selected':''}>Mata-mata</option></select><button class="smallbtn" data-phase-remove>Excluir</button></div>`}
async function saveCompetitionConfig(){if(!canOperate())return;const rows=[...document.querySelectorAll('[data-phase-row]')];const phases=rows.map((r,i)=>({name:r.querySelector('[data-phase-name]').value.trim()||`Fase ${i+1}`,type:r.querySelector('[data-phase-type]').value}));if(!phases.length)return toast('Inclua pelo menos uma fase.','error');const {error}=await supabase.from('competitions').update({group_count:Number(document.querySelector('#cfgGroupCount').value),phases}).eq('id',state.competition.id);if(error)return toast(error.message,'error');document.querySelector('#competitionConfigModal')?.remove();await load();toast('Configuração do campeonato salva.');}
function sponsorsView(){return `<section class="panel"><div class="panelhead"><div><h2>Patrocinadores</h2><p class="muted">Parceiros oficiais da competição.</p></div>${canOperate()?'<button class="primary" data-sponsor-new>+ Incluir patrocinador</button>':''}</div><div class="flags">${state.sponsors.filter(s=>s.active).sort((a,b)=>a.sort_order-b.sort_order).map(s=>`<div class="sponsor-card">${s.logo_url?`<img src="${esc(s.logo_url)}" alt="${esc(s.name)}">`:''}<b>${esc(s.name)}</b>${s.website?`<a href="${esc(s.website)}" target="_blank">Site</a>`:''}${canOperate()?`<button class="smallbtn" data-sponsor-edit="${s.id}">Alterar</button><button class="smallbtn" data-sponsor-delete="${s.id}">Excluir</button>`:''}</div>`).join('')}</div></section>`}
function mediaView(){const photos=state.media.filter(x=>x.category==='foto'),videos=state.media.filter(x=>x.category==='video'),files=state.media.filter(x=>!['foto','video'].includes(x.category));return `<section class="panel"><div class="panelhead"><div><h2>Fotos / Arquivos / Vídeos</h2><p class="muted">Biblioteca oficial da Copa.</p></div>${canOperate()?'<button class="primary" data-media-new>+ Adicionar foto, vídeo ou arquivo</button>':''}</div><h3>Fotos</h3><div class="media-grid">${photos.length?photos.map(mediaCard).join(''):'<div class="empty">Nenhuma foto cadastrada.</div>'}</div><h3>Vídeos</h3><div class="media-grid video-grid">${videos.length?videos.map(mediaCard).join(''):'<div class="empty">Nenhum vídeo cadastrado.</div>'}</div><h3>Arquivos</h3><div class="media-list">${files.length?files.map(mediaCard).join(''):'<div class="empty">Nenhum arquivo cadastrado.</div>'}</div></section>`}
function mediaCard(x){const isImg=x.mime_type?.startsWith('image/'),isVideo=x.mime_type?.startsWith('video/');return `<div class="media-card">${isImg?`<img src="${esc(x.file_url)}" alt="${esc(x.title)}">`:isVideo?`<video src="${esc(x.file_url)}" controls preload="metadata"></video>`:'📄'}<b>${esc(x.title)}</b>${x.description?`<small>${esc(x.description)}</small>`:''}<a class="smallbtn" href="${esc(x.file_url)}" target="_blank">Abrir</a>${canOperate()?`<button class="smallbtn" data-media-delete="${x.id}">Excluir</button>`:''}</div>`}
function reportsView(){const counts={jogos:state.matches.length,atletas:state.players.length,equipes:state.teams.length,cartoes:state.events.filter(e=>e.type?.includes('cartao')).length,artilheiros:state.allEvents.filter(e=>e.type==='gol').length};return `<section class="panel"><div class="panelhead"><div><h2>Relatórios</h2><p class="muted">Escolha um relatório e imprima ou salve em PDF pelo navegador.</p></div></div><div class="report-buttons">${['jogos','atletas','atletas_equipe','artilheiros','equipes','cartoes','classificacao','grupos'].map(x=>`<button class="secondary" data-report="${x}">${({jogos:'Jogos',atletas:'Atletas',atletas_equipe:'Atletas por equipe',artilheiros:'Artilheiros',equipes:'Equipes',cartoes:'Cartões',classificacao:'Classificação',grupos:'Classificação por grupos'})[x]}</button>`).join('')}</div>${state.reportType?reportContent(state.reportType):'<div class="empty">Selecione um relatório.</div>'}</section>`}
function reportContent(type){let title=({jogos:'Relatório de jogos',atletas:'Relatório de atletas',atletas_equipe:'Relação de atletas por equipes',artilheiros:'Artilharia',equipes:'Relatório de equipes',cartoes:'Cartões',classificacao:'Classificação geral',grupos:'Classificação por grupos'})[type];let body='';if(type==='jogos')body=matchesTable(false);if(type==='atletas'||type==='atletas_equipe'){if(type==='atletas_equipe'){body=state.teams.map(t=>{const ps=state.players.filter(p=>p.team_id===t.id).sort((a,b)=>{const na=Number(a.shirt_number),nb=Number(b.shirt_number);if(Number.isFinite(na)&&Number.isFinite(nb))return na-nb;if(Number.isFinite(na))return -1;if(Number.isFinite(nb))return 1;return (a.full_name||a.name||'').localeCompare(b.full_name||b.name||'')});return `<div class="report-team"><h3>${flag(t.name)} ${esc(t.name)}</h3><div class="tablewrap"><table><tr><th>Nº</th><th>Atleta</th><th>Apelido</th><th>Categoria</th><th>Posição</th><th>Nascimento</th></tr>${ps.map(p=>`<tr><td><b>${p.shirt_number||'—'}</b></td><td>${esc(p.full_name||p.name)}</td><td>${esc(p.nickname||'')}</td><td>${esc(p.category||'')}</td><td>${esc(p.position||'')}</td><td>${p.birth_date?esc(p.birth_date):'—'}</td></tr>`).join('')}</table></div></div>`}).join('')}else body=`<div class="tablewrap"><table><tr><th>Atleta</th><th>Equipe</th><th>Número</th><th>Posição</th></tr>${state.players.map(p=>`<tr><td>${esc(p.full_name||p.name)}</td><td>${esc(teamName(p.team_id))}</td><td>${p.shirt_number||''}</td><td>${esc(p.position||'')}</td></tr>`).join('')}</table></div>`}if(type==='equipes')body=`<div class="tablewrap"><table><tr><th>Equipe</th><th>Grupo</th></tr>${state.teams.map(t=>`<tr><td>${flag(t.name)} ${esc(t.name)}</td><td>${esc(state.groups.find(g=>g.id===t.group_id)?.name||'—')}</td></tr>`).join('')}</table></div>`;if(type==='artilheiros'){const map={};state.allEvents.filter(e=>e.type==='gol'&&e.player_id).forEach(e=>map[e.player_id]=(map[e.player_id]||0)+1);body=`<div class="tablewrap"><table><tr><th>#</th><th>Atleta</th><th>Equipe</th><th>Gols</th></tr>${Object.entries(map).sort((a,b)=>b[1]-a[1]).map(([id,n],i)=>`<tr><td>${i+1}</td><td>${esc(playerName(id))}</td><td>${esc(teamName(state.players.find(p=>p.id===id)?.team_id))}</td><td><b>${n}</b></td></tr>`).join('')}</table></div>`}if(type==='cartoes'){const map={};state.allEvents.filter(e=>['cartao_amarelo','cartao_vermelho'].includes(e.type)&&e.player_id).forEach(e=>{const k=e.player_id+'|'+e.type;map[k]=(map[k]||0)+1});body=`<div class="tablewrap"><table><tr><th>Atleta</th><th>Equipe</th><th>Tipo</th><th>Quantidade</th></tr>${Object.entries(map).map(([k,n])=>{const [id,t]=k.split('|');return `<tr><td>${esc(playerName(id))}</td><td>${esc(teamName(state.players.find(p=>p.id===id)?.team_id))}</td><td>${t==='cartao_amarelo'?'Amarelo':'Vermelho'}</td><td>${n}</td></tr>`}).join('')}</table></div>`}if(type==='classificacao')body=standingsTable(calcStandings());if(type==='grupos')body=state.groups.slice().sort((a,b)=>a.position-b.position).map(g=>`<h3>${esc(g.name)}</h3>${standingsTable(calcStandings(state.teams.filter(t=>t.group_id===g.id).map(t=>t.id)))}`).join('');return `<div class="report-preview"><div class="panelhead"><h3>${title}</h3><button class="primary" data-print-report>🖨️ Imprimir / PDF</button></div>${body}</div>`}
function matchCard(m){const h=teamName(m.home_team_id),a=teamName(m.away_team_id);return `<div class="matchmini"><div>${flag(h)} <b>${esc(h)}</b></div><div class="scoremini">${m.home_score}<span>×</span>${m.away_score}</div><div><b>${esc(a)}</b> ${flag(a)}</div><button class="smallbtn" data-open-match="${m.id}">Súmula</button></div>`}
function liveSheet(){const m=state.selectedMatch;if(!m)return '';const h=teamName(m.home_team_id),a=teamName(m.away_team_id);const official=(id,label)=>{const r=state.referees.find(x=>x.id===id);return r?`<span><b>${label}:</b> ${esc(r.name)}</span>`:''};return `<div class="live-sheet"><div class="sheet-head"><div><span class="status">${m.reopened_at&&m.status==='agendado'?'REABERTA':m.status.toUpperCase()}</span><div class="match-goals"><div class="goal-team"><div class="goal-buttons"><button class="goalbtn" data-score-dec="${m.home_team_id}">−</button><strong>${m.home_score||0}</strong><button class="goalbtn" data-score-inc="${m.home_team_id}">+</button></div><b>${flag(h)} ${esc(h)}</b></div><div class="goal-x">×</div><div class="goal-team"><div class="goal-buttons"><button class="goalbtn" data-score-dec="${m.away_team_id}">−</button><strong>${m.away_score||0}</strong><button class="goalbtn" data-score-inc="${m.away_team_id}">+</button></div><b>${esc(a)} ${flag(a)}</b></div></div><p class="muted">${fmtDate(m.scheduled_at)} • ${esc(m.field_name||'Campo não informado')}</p><div class="officials">${official(m.referee_id,'Árbitro')}${official(m.assistant_1_id,'Assistente 1')}${official(m.assistant_2_id,'Assistente 2')}${official(m.fourth_official_id,'Mesário')}</div></div><div class="clock"><div id="matchClock">${matchClock(m)}</div><small>${state.timerHalf==='2T'?'2º TEMPO':state.timerHalf==='1T'?'1º TEMPO':m.status==='encerrado'?'ENCERRADO':'PARADO'}</small></div></div>${controlBar(m)}${correctionPanel(m)}<div class="sheet-grid"><div class="sheet-main">${eventPanel(m)}${eventTimeline()}</div><div class="sheet-side">${lineupPanel(m)}${votePanel(m)}</div></div></div>`}
function matchClock(m){if(state.timerHalf)return fmtSec(elapsedSeconds(m));if(m?.status==='encerrado')return fmtSec((m.second_half_elapsed_seconds||0)+(m.first_half_elapsed_seconds||0));return '00:00'}
function fmtSec(s){const min=Math.floor(s/60),sec=s%60;return String(min).padStart(2,'0')+':'+String(sec).padStart(2,'0')}
function controlBar(m){const disabled=!canOperate()||m.status==='encerrado';return `<div class="controlbar"><button class="primary" ${disabled?'disabled':''} data-action="start1">▶ Iniciar 1º tempo</button><button ${disabled?'disabled':''} data-action="start2">▶ Iniciar 2º tempo</button><button ${disabled?'disabled':''} data-action="pause">⏸ Pausar</button><button ${disabled?'disabled':''} data-minute-adjust="1">+ 1 min</button><button ${disabled?'disabled':''} data-clock-adjust="1">+ 1 seg</button><button ${disabled?'disabled':''} data-minute-adjust="-1">− 1 min</button><button ${disabled?'disabled':''} data-clock-adjust="-1">− 1 seg</button><button class="danger" ${disabled?'disabled':''} data-action="finish">■ Encerrar partida</button></div>`}
function correctionPanel(m){if(!canOperate()||!m.reopened_at||m.status!=='agendado')return '';return `<div class="panel correction"><div class="panelhead"><div><h3>🔧 Correção da partida</h3><p class="muted">Partida reaberta. Você pode corrigir o resultado e os eventos.</p></div></div><div class="eventform"><label>Placar ${esc(teamName(m.home_team_id))}<input id="corrHome" type="number" min="0" value="${m.home_score||0}"></label><label>Placar ${esc(teamName(m.away_team_id))}<input id="corrAway" type="number" min="0" value="${m.away_score||0}"></label><button class="primary" data-action="saveScoreCorrection">💾 Salvar resultado</button></div></div>`}
function eventPanel(m){const players=state.players.filter(p=>p.team_id===m.home_team_id||p.team_id===m.away_team_id).sort((a,b)=>{const na=Number(a.shirt_number),nb=Number(b.shirt_number);if(Number.isFinite(na)&&Number.isFinite(nb))return na-nb;if(Number.isFinite(na))return -1;if(Number.isFinite(nb))return 1;return (a.full_name||a.name||'').localeCompare(b.full_name||b.name||'')});const opt=p=>`${p.shirt_number?`#${p.shirt_number} - `:''}${esc(p.full_name||p.name)} - ${esc(teamName(p.team_id))}`;const last=state.events.slice().reverse().find(e=>e.type==='substituicao');const editing=state.editingSubId?state.events.find(e=>e.id===state.editingSubId):null;return `<div class="eventpanel"><div class="panelhead"><h3>Registrar ocorrência</h3><span class="muted">${state.events.length} eventos</span></div>${!canOperate()?'<div class="notice">🔒 Faça login com perfil de administrador, organizador, árbitro ou operador para registrar ocorrências.</div>':''}<div class="eventform"><select id="eventType"><option value="gol">⚽ Gol</option><option value="gol_contra">🥅 Gol Contra</option><option value="cartao_amarelo">🟨 Cartão amarelo</option><option value="cartao_vermelho">🟥 Cartão vermelho</option><option value="incidente">📝 Incidente</option></select><select id="eventTeam"><option value="">Equipe</option><option value="${m.home_team_id}">${esc(teamName(m.home_team_id))}</option><option value="${m.away_team_id}">${esc(teamName(m.away_team_id))}</option></select><select id="eventPlayer"><option value="">Atleta</option>${players.map(p=>`<option value="${p.id}">${opt(p)}</option>`).join('')}</select><div class="event-clock-box"><button type="button" class="smallbtn" data-event-clock-adjust="60" ${!canOperate()?'disabled':''}>+ 1 min</button><button type="button" class="smallbtn" data-event-clock-adjust="-60" ${!canOperate()?'disabled':''}>− 1 min</button><span class="event-clock" id="eventClock">${fmtSec(state.eventClockSeconds)}</span><button type="button" class="smallbtn" data-event-clock-adjust="1" ${!canOperate()?'disabled':''}>+ 1 seg</button><button type="button" class="smallbtn" data-event-clock-adjust="-1" ${!canOperate()?'disabled':''}>− 1 seg</button><button type="button" class="smallbtn primary" data-event-timer="toggle" ${!canOperate()?'disabled':''}>${state.eventTimerStartedAt?'⏸ Pausar':'▶ Cronômetro'}</button><button type="button" class="smallbtn" data-event-timer="reset" ${!canOperate()?'disabled':''}>↺ Zerar</button></div><input id="eventMinute" type="hidden" value="${Math.floor(state.eventClockSeconds/60)}"/><div class="occurrence-actions"><button class="secondary" type="button" data-occurrence-edit-last ${!canOperate()?'disabled':''}>✏️ Alterar</button><button class="danger" type="button" data-occurrence-delete-last ${!canOperate()?'disabled':''}>🗑️ Excluir</button><button class="primary" type="button" data-action="event" ${!canOperate()?'disabled':''}>💾 Salvar</button></div></div><div class="subform"><select id="subOut"><option value="">Sai</option>${players.map(p=>`<option value="${p.id}" ${editing?.player_id===p.id?'selected':''}>${opt(p)}</option>`).join('')}</select><select id="subIn"><option value="">Entra</option>${players.map(p=>`<option value="${p.id}" ${editing?.related_player_id===p.id?'selected':''}>${opt(p)}</option>`).join('')}</select><span class="sub-clock-inline"><span class="event-clock">${fmtSec(state.eventClockSeconds)}</span><button type="button" class="smallbtn" data-event-timer="toggle" ${!canOperate()?'disabled':''}>${state.eventTimerStartedAt?'⏸':'▶'} Cronômetro</button></span><button class="secondary" ${!canOperate()?'disabled':''} data-action="sub">${editing?'💾 Salvar substituição':'Registrar substituição'}</button>${editing?`<button class="smallbtn" type="button" data-sub-cancel="1">Cancelar</button>`:(last&&canOperate()?`<button class="smallbtn" type="button" data-sub-edit="${last.id}">✏️ Alterar / Salvar</button><button class="smallbtn danger" type="button" data-sub-delete="${last.id}">🗑️ Excluir</button>`:'')}</div></div>`}

function elapsedSeconds(m){const half=state.timerHalf;let base=0;if(half==='1T')base=m?.first_half_elapsed_seconds||0;else if(half==='2T')base=m?.second_half_elapsed_seconds||0;else return 0;return base+(state.timerStartedAt?Math.max(0,Math.floor((Date.now()-new Date(state.timerStartedAt).getTime())/1000)):0)}
function currentMinute(){return Math.floor(state.eventClockSeconds/60)}
function currentClock(){return fmtSec(state.eventClockSeconds)}
function adjustEventClock(delta){if(!canOperate())return;state.eventClockSeconds=Math.max(0,state.eventClockSeconds+delta);updateEventClockDom()}
function updateEventClockDom(){const t=fmtSec(state.eventClockSeconds);document.querySelectorAll('#eventClock,.sub-clock-inline .event-clock').forEach(el=>el.textContent=t);const mi=document.querySelector('#eventMinute');if(mi)mi.value=Math.floor(state.eventClockSeconds/60)}
function toggleEventTimer(){if(!canOperate())return;if(state.eventTimerStartedAt){state.eventClockSeconds+=Math.max(0,Math.floor((Date.now()-new Date(state.eventTimerStartedAt).getTime())/1000));state.eventTimerStartedAt=null;stopEventTicker()}else{state.eventTimerStartedAt=new Date().toISOString();startEventTicker()}render()}
function resetEventTimer(){if(!canOperate())return;state.eventTimerStartedAt=null;stopEventTicker();state.eventClockSeconds=0;render()}
function startEventTicker(){stopEventTicker();state.eventTimerInterval=setInterval(()=>{const base=state.eventClockSeconds;const running=state.eventTimerStartedAt?Math.max(0,Math.floor((Date.now()-new Date(state.eventTimerStartedAt).getTime())/1000)):0;const t=fmtSec(base+running);document.querySelectorAll('#eventClock,.sub-clock-inline .event-clock').forEach(el=>el.textContent=t);const mi=document.querySelector('#eventMinute');if(mi)mi.value=Math.floor((base+running)/60)},1000)}
function stopEventTicker(){if(state.eventTimerInterval)clearInterval(state.eventTimerInterval);state.eventTimerInterval=null}
function eventTimeline(){const editable=canOperate();return `<div class="timeline"><h3>Eventos da partida</h3>${state.events.length?state.events.slice().reverse().map(e=>`<div class="eventrow"><span class="eventicon">${eventIcon(e.type)}</span><div><b>${esc(eventLabel(e.type))}</b> <span class="muted">${e.minute??'—'}${Number.isFinite(Number(e.second))?`:${String(e.second).padStart(2,'0')}`:''}</span><div>${e.player_id?esc(playerName(e.player_id)):''}${e.related_player_id?` → ${esc(playerName(e.related_player_id))}`:''}</div></div><span class="muted">${esc(teamName(e.team_id))}${editable?` <button class="smallbtn" data-event-edit="${e.id}">✏️ Alterar</button><button class="smallbtn danger" data-event-delete="${e.id}">🗑️ Excluir</button>`:''}</span></div>`).join(''):`<div class="empty">Nenhuma ocorrência registrada.</div>`}</div>`}
function eventIcon(t){return {gol:'⚽',gol_contra:'🥅',cartao_amarelo:'🟨',cartao_vermelho:'🟥',substituicao:'🔄',incidente:'📝'}[t]||'•'}
function eventLabel(t){return {gol:'Gol',gol_contra:'Gol Contra',cartao_amarelo:'Cartão amarelo',cartao_vermelho:'Cartão vermelho',substituicao:'Substituição',incidente:'Incidente'}[t]||t}
function lineupStatusLabel(st){return st==='titular'?'Titular':st==='nao_compareceu'?'Não compareceu':'Reserva'}
function lineupPanel(m){const teamBlocks=[m.home_team_id,m.away_team_id].map(tid=>{const ps=state.players.filter(p=>p.team_id===tid).sort((a,b)=>(a.shirt_number||999)-(b.shirt_number||999));return `<div class="lineupteam"><h4>${flag(teamName(tid))} ${esc(teamName(tid))}</h4>${ps.length?ps.map(p=>{const l=state.lineups.find(x=>x.player_id===p.id);const st=l?.status||'reserva';return `<div class="playerline compact-playerline"><span>${p.shirt_number?`#${p.shirt_number} `:''}${esc(p.name)}</span><button class="statusbtn status-${st}" data-lineup-status="${p.id}" data-status="${st}" ${!canOperate()?'disabled':''}>${lineupStatusLabel(st)}</button></div>`}).join(''):'<div class="muted">Nenhum atleta cadastrado.</div>'}</div>`}).join('');return `<div class="lineuppanel"><div class="panelhead"><h3>Súmula / escalação</h3><button class="secondary" data-action="saveLineup" ${!canOperate()?'disabled':''}>Salvar situação dos atletas</button></div><p class="muted">Clique no botão de cada atleta para escolher a situação.</p>${teamBlocks}</div>`}
function lineupStatusModal(id){const btn=document.querySelector(`[data-lineup-status="${id}"]`);if(!btn)return;const current=btn.dataset.status||'reserva';document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="lineupStatusModal"><div class="modalbox lineup-status-modal"><button class="close" data-close>×</button><div class="eyebrow">ESCALAÇÃO</div><h2>Escolha a situação</h2><div class="status-options"><button class="status-option ${current==='titular'?'selected':''}" data-lineup-choice="${id}" data-status="titular">🟢 Titular</button><button class="status-option ${current==='reserva'?'selected':''}" data-lineup-choice="${id}" data-status="reserva">⚪ Reserva</button><button class="status-option ${current==='nao_compareceu'?'selected':''}" data-lineup-choice="${id}" data-status="nao_compareceu">🔴 Não compareceu</button></div></div></div>`)}
function votePanel(m){const candidates=state.players.filter(p=>state.lineups.some(l=>l.match_id===m.id&&l.player_id===p.id&&l.status==='titular'));const counts=state.votes.reduce((a,v)=>(a[v.player_id]=(a[v.player_id]||0)+1,a),{});return `<div class="votepanel"><h3>Melhor jogador da partida</h3>${candidates.length?candidates.sort((a,b)=>(counts[b.id]||0)-(counts[a.id]||0)).map(p=>`<button class="vote" data-vote="${p.id}" ${!state.session?'disabled':''}>⭐ ${esc(p.name)} <b>${counts[p.id]||0}</b></button>`).join(''):'<div class="muted">Defina a escalação titular para liberar os candidatos.</div>'}</div>`}
function standingsView(){const rows=state.teams.map(t=>({team:t,j:0,v:0,e:0,d:0,gp:0,gc:0,pts:0}));const map=new Map(rows.map(r=>[r.team.id,r]));state.matches.filter(m=>m.status==='encerrado').forEach(m=>{const h=map.get(m.home_team_id),a=map.get(m.away_team_id);if(!h||!a)return;h.j++;a.j++;h.gp+=m.home_score||0;h.gc+=m.away_score||0;a.gp+=m.away_score||0;a.gc+=m.home_score||0;if(m.home_score>m.away_score){h.v++;h.pts+=3;a.d++}else if(m.home_score<m.away_score){a.v++;a.pts+=3;h.d++}else{h.e++;a.e++;h.pts++;a.pts++}});rows.sort((a,b)=>b.pts-a.pts||(b.gp-b.gc)-(a.gp-a.gc)||b.gp-a.gp||a.team.name.localeCompare(b.team.name));return `<section class="panel"><div class="panelhead"><div><h2>Classificação geral</h2><p class="muted">Calculada automaticamente com as partidas encerradas.</p></div><span class="tag">${state.matches.filter(m=>m.status==='encerrado').length} jogos concluídos</span></div>${classificationTabs('geral')}<div class="tablewrap"><table><tr><th>#</th><th>Time</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th><th>Pts</th></tr>${rows.map((r,i)=>`<tr><td><b>${i+1}</b></td><td>${flag(r.team.name)} ${esc(r.team.name)}</td><td>${r.j}</td><td>${r.v}</td><td>${r.e}</td><td>${r.d}</td><td>${r.gp}</td><td>${r.gc}</td><td>${r.gp-r.gc}</td><td><b>${r.pts}</b></td></tr>`).join('')}</table></div></section>`}
function list(title,items,type){
  const data = type==='team' ? state.teams : type==='player' ? state.players : type==='referee' ? state.referees : [];
  const rows = data.map(r=>{
    const label = type==='team' ? flag(r.name)+' '+esc(r.name) : type==='player' ? `${r.photo_url?`<img class="avatar-sm" src="${esc(r.photo_url)}" alt="">`:''}${esc(r.full_name||r.name)}` : esc(r.name);
    const detail = type==='team' ? esc(r.country||'Seleção') : type==='player' ? `${esc(r.nickname||'')} ${r.nickname?'• ':''}${esc(teamName(r.team_id))} • ${esc(r.category||'')} • ${esc(r.position||'')} ${r.shirt_number?`• #${r.shirt_number}`:''}` : esc(r.registration||'Árbitro');
    return `<tr><td><b>${label}</b></td><td>${detail}</td>${canOperate()?`<td class="actions"><button class="smallbtn" data-edit-crud="${type}" data-id="${r.id}">✏️ Alterar</button><button class="danger smallbtn" data-delete-crud="${type}" data-id="${r.id}">🗑️ Excluir</button></td>`:''}</tr>`
  }).join('');
  return `<section class="panel"><div class="panelhead"><h2>${title}</h2><div class="panelhead"><span class="tag">${items.length} registros</span>${canOperate()&&type?`<button class="primary" data-crud="${type}">➕ Incluir</button>`:''}</div></div>${data.length?`<div class="tablewrap"><table><tr><th>Nome</th><th>Detalhes</th>${canOperate()?'<th>Ações</th>':''}</tr>${rows}</table></div>`:`<div class="empty">Nenhum registro cadastrado.</div>`}</section>`
}

async function adjustScore(teamId,delta){if(!canOperate()||!state.selectedMatch)return;const m=state.selectedMatch;if(m.status==='encerrado')return;const field=teamId===m.home_team_id?'home_score':'away_score';const value=Math.max(0,Number(m[field]||0)+delta);const {error}=await supabase.from('matches').update({[field]:value}).eq('id',m.id);if(error)return toast(error.message,'error');await load();await loadMatchDetails(m.id,false);render()}
async function adjustClock(deltaSeconds){if(!canOperate()||!state.selectedMatch)return;const m=state.selectedMatch;const half=state.timerHalf||'1T';const field=half==='2T'?'second_half_elapsed_seconds':'first_half_elapsed_seconds';const current=elapsedSeconds(m);const value=Math.max(0,current+deltaSeconds);const running=!!state.timerStartedAt;const {error}=await supabase.from('matches').update({[field]:value}).eq('id',m.id);if(error)return toast(error.message,'error');state.timerStartedAt=running?new Date().toISOString():null;await load();if(running)startTicker();}
async function adjustMinute(delta){return adjustClock(delta*60)}
async function adjustSecond(delta){return adjustClock(delta)}

async function updateMatch(values){if(!canOperate()||!state.selectedMatch)return toast('Acesso operacional necessário.','error');const {error}=await supabase.from('matches').update(values).eq('id',state.selectedMatch.id);if(error)return toast(error.message,'error');await load();}
async function startHalf(half){if(!canOperate())return toast('Entre com perfil autorizado.','error');const m=state.selectedMatch;if(!m)return;const now=new Date().toISOString();state.timerHalf=half;state.timerStartedAt=now;const values=half==='1T'?{status:'ao_vivo',first_half_started_at:now}:{status:'ao_vivo',second_half_started_at:now};await updateMatch(values);startTicker()}
async function pause(){if(!canOperate()||!state.selectedMatch)return;const m=state.selectedMatch;if(!state.timerStartedAt){stopTicker();return}const elapsed=Math.max(0,Math.floor((Date.now()-new Date(state.timerStartedAt).getTime())/1000));const field=state.timerHalf==='2T'?'second_half_elapsed_seconds':'first_half_elapsed_seconds';const values={[field]:(m[field]||0)+elapsed};state.timerStartedAt=null;stopTicker();await updateMatch(values);state.timerHalf=state.timerHalf||'1T';toast('Cronômetro pausado e tempo salvo.');}
async function finishMatch(){if(!canOperate())return toast('Entre com perfil autorizado.','error');if(!confirm('Encerrar esta partida e confirmar o placar?'))return;if(state.timerStartedAt)await pause();await updateMatch({status:'encerrado',finished_at:new Date().toISOString()});state.timerStartedAt=null;stopTicker();state.timerHalf=null;await loadMatchDetails(state.selectedMatch.id,false);render()}
async function addEvent(){if(!canOperate())return toast('Acesso operacional necessário.','error');const m=state.selectedMatch;if(!m)return;const type=document.querySelector('#eventType')?.value,team_id=document.querySelector('#eventTeam')?.value||null,player_id=document.querySelector('#eventPlayer')?.value||null;const total=state.eventClockSeconds+(state.eventTimerStartedAt?Math.max(0,Math.floor((Date.now()-new Date(state.eventTimerStartedAt).getTime())/1000)):0);const minute=Math.floor(total/60),second=total%60;if(type!=='incidente'&&!team_id)return toast('Selecione a equipe.','error');if(type!=='incidente'&&!player_id)return toast('Selecione o atleta.','error');const {error}=await supabase.from('match_events').insert({match_id:m.id,team_id,player_id,minute,second,added_minute:null,description:null,type,created_by:state.session.user.id});if(error)return toast(error.message,'error');if(type==='gol'||type==='gol_contra'){const scoringTeam=type==='gol_contra'?(team_id===m.home_team_id?m.away_team_id:m.home_team_id):team_id;const field=scoringTeam===m.home_team_id?'home_score':'away_score';await supabase.from('matches').update({[field]:(m[field]||0)+1}).eq('id',m.id)}await loadMatchDetails(m.id,false);await load();toast('Ocorrência salva.');}
async function saveCrud(type,id=''){
  if(!canOperate())return;
  let row={};
  if(type==='team') row={competition_id:state.competition.id,name:document.querySelector('#fName').value.trim(),country:document.querySelector('#fCountry').value.trim()||null,group_id:document.querySelector('#fGroup').value||null};
  if(type==='player'){const full=document.querySelector('#fFullName').value.trim();row={team_id:document.querySelector('#fTeam').value,name:full,full_name:full,nickname:document.querySelector('#fNickname').value.trim()||null,birth_date:document.querySelector('#fBirthDate').value||null,category:document.querySelector('#fCategory').value||null,shirt_number:Number(document.querySelector('#fNumber').value)||null,position:document.querySelector('#fPosition').value||null};const photo=document.querySelector('#fPhotoFile')?.files?.[0];if(photo){const target=id||crypto.randomUUID();const path=`${state.competition.id}/players/${target}-${Date.now()}-${photo.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('ouro-prata-arquivos').upload(path,photo,{upsert:true});if(up.error)return toast(up.error.message,'error');row.photo_path=path;row.photo_url=supabase.storage.from('ouro-prata-arquivos').getPublicUrl(path).data.publicUrl;}else if(id){row.photo_url=current?.photo_url||null;row.photo_path=current?.photo_path||null;}}
  if(type==='referee') row={name:document.querySelector('#fName').value.trim(),registration:document.querySelector('#fReg').value.trim()||null,phone:document.querySelector('#fPhone').value.trim()||null};
  if(type==='match'){const h=document.querySelector('#fHome').value,a=document.querySelector('#fAway').value;if(h===a)return toast('O mandante e o visitante devem ser diferentes.','error');const dt=document.querySelector('#fDate').value;row={competition_id:state.competition.id,group_id:document.querySelector('#fMatchGroup').value||null,home_team_id:h,away_team_id:a,referee_id:document.querySelector('#fRef').value||null,assistant_1_id:document.querySelector('#fAssistant1').value||null,assistant_2_id:document.querySelector('#fAssistant2').value||null,fourth_official_id:document.querySelector('#fFourth').value||null,scheduled_at:dt?new Date(dt).toISOString():null,field_name:document.querySelector('#fField').value.trim()||null}};
  if(!row.name && ['team','player','referee'].includes(type))return toast('Informe o nome.','error');
  const table={team:'teams',player:'players',referee:'referees',match:'matches'}[type];
  const answer=await askConfirm(id?'Confirma ALTERAR este cadastro?':'Confirma SALVAR este cadastro?'); if(!answer)return;
  const result=id?await supabase.from(table).update(row).eq('id',id):await supabase.from(table).insert(row);
  if(result.error)return toast(result.error.message,'error');
  document.querySelector('#crudModal')?.remove();toast(id?'Cadastro alterado com sucesso.':'Cadastro salvo com sucesso.');await load();
}
async function deleteCrud(type,id){
  if(!canOperate())return;
  const table={team:'teams',player:'players',referee:'referees',match:'matches'}[type];
  const label=type==='team'?teamName(id):type==='player'?playerName(id):type==='referee'?(state.referees.find(x=>x.id===id)?.name||'este árbitro'):'este jogo';
  const ok=await askConfirm(`Deseja EXCLUIR ${label}? Esta ação não pode ser desfeita.`); if(!ok)return;
  const {error}=await supabase.from(table).delete().eq('id',id);if(error)return toast(error.message,'error');toast('Cadastro excluído com sucesso.');await load();
}
function askConfirm(message){return new Promise(resolve=>{const old=document.querySelector('#confirmModal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="confirmModal"><div class="modalbox"><div class="eyebrow">CONFIRMAÇÃO</div><h2>Confirmação</h2><p>${esc(message)}</p><div class="modal-actions"><button class="secondary" id="confirmNo">NÃO</button><button class="danger" id="confirmYes">SIM</button></div></div></div>`);document.querySelector('#confirmNo').onclick=()=>{document.querySelector('#confirmModal')?.remove();resolve(false)};document.querySelector('#confirmYes').onclick=()=>{document.querySelector('#confirmModal')?.remove();resolve(true)}})}

async function authSubmit(){const email=document.querySelector('#authEmail')?.value.trim(),password=document.querySelector('#authPassword')?.value;if(!email||!password)return toast('Informe e-mail e senha.','error');let res;if(state.authMode==='signup')res=await supabase.auth.signUp({email,password});else res=await supabase.auth.signInWithPassword({email,password});if(res.error)return toast(res.error.message,'error');if(state.authMode==='signup')toast('Usuário criado. Se a confirmação de e-mail estiver ativa, confirme o e-mail antes de entrar.','ok');else toast('Login realizado.','ok');await load();}
async function logout(){await supabase.auth.signOut();state.session=null;state.profile=null;render()}
function openAuth(){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="authModal"><div class="modalbox"><button class="close" data-close>×</button><div class="eyebrow">ACESSO AO SISTEMA</div><h2>${state.authMode==='signup'?'Criar usuário':'Entrar'}</h2><p class="muted">Para operar a súmula, use um usuário com perfil autorizado no Supabase.</p><input id="authEmail" type="email" placeholder="E-mail"><input id="authPassword" type="password" placeholder="Senha"><button class="primary wide" data-auth-submit>${state.authMode==='signup'?'Criar usuário':'Entrar'}</button><button class="linkbtn" data-toggle-auth>${state.authMode==='signup'?'Já tenho cadastro':'Criar novo usuário'}</button></div></div>`)}
function toast(msg,type='ok'){document.querySelectorAll('.toast').forEach(x=>x.remove());document.body.insertAdjacentHTML('beforeend',`<div class="toast ${type}">${esc(msg)}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),3500)}
function startTicker(){stopTicker();state.timerInterval=setInterval(()=>{const el=document.querySelector('#matchClock');if(el)el.textContent=matchClock(state.selectedMatch);const ev=document.querySelector('#eventClock');if(ev)ev.textContent=currentClock();const mi=document.querySelector('#eventMinute');if(mi)mi.value=currentMinute()},1000)}
function stopTicker(){if(state.timerInterval)clearInterval(state.timerInterval);state.timerInterval=null}

function ensureCustomStyles(){if(document.querySelector('#ouroCustomStyles'))return;document.head.insertAdjacentHTML('beforeend',`<style id="ouroCustomStyles">.match-goals{display:flex;align-items:center;justify-content:center;gap:18px;margin:12px 0 8px}.goal-team{display:flex;flex-direction:column;align-items:center;gap:7px;min-width:120px}.goal-buttons{display:flex;align-items:center;gap:5px}.goalbtn{width:34px;height:34px;border:1px solid #cbd5d1;border-radius:7px;background:#f5f8f6;font-size:20px;font-weight:700;cursor:pointer}.goal-buttons strong{min-width:38px;text-align:center;font-size:25px}.goal-x{font-size:22px;font-weight:700}.officials{display:flex;flex-wrap:wrap;gap:7px;margin-top:8px}.officials span{padding:5px 9px;border-radius:8px;background:#f1f5f3;font-size:12px}.compact-playerline{display:flex;align-items:center;justify-content:space-between;gap:6px}.statusbtn{width:108px;min-width:108px;border:0;border-radius:8px;padding:7px 5px;font-size:12px;cursor:pointer}.status-titular{background:#dff3e7;color:#17633e}.status-reserva{background:#edf1ef;color:#376052}.status-nao_compareceu{background:#fde4e4;color:#8b3030}.status-options{display:grid;gap:10px;margin-top:15px}.status-option{padding:13px;border:1px solid #d5ded9;border-radius:10px;background:#f7faf8;text-align:left;font-size:15px;cursor:pointer}.status-option.selected{border-color:#168458;background:#e5f4ed}.phase-row{display:grid;grid-template-columns:1fr 170px auto;gap:8px;margin:8px 0}.phase-head{display:flex;align-items:center;justify-content:space-between;margin:14px 0 8px}.event-clock{display:inline-flex;align-items:center;justify-content:center;min-width:70px;height:42px;padding:0 9px;border-radius:8px;background:#0b4d37;color:white;font-weight:700;font-variant-numeric:tabular-nums}.group-box{margin-top:12px}.config-modal{max-width:650px}.class-tabs{display:flex;gap:8px;margin:12px 0}.class-tabs button{border:1px solid #d4ded9;background:#f4f8f6;border-radius:9px;padding:9px 14px;cursor:pointer}.class-tabs button.active{background:#0b6b49;color:#fff;border-color:#0b6b49}.avatar-sm{width:34px;height:34px;object-fit:cover;border-radius:50%;vertical-align:middle;margin-right:8px}.player-photo-preview{display:block;width:80px;height:80px;object-fit:cover;border-radius:10px;margin-top:8px}.file-field{display:flex;flex-direction:column;gap:5px}.video-grid video{width:100%;max-height:220px;border-radius:10px}.eventform{grid-template-columns:repeat(3,minmax(0,1fr))}.subform{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;align-items:center}.event-clock-box{grid-column:1/-1;display:flex;align-items:center;gap:6px;flex-wrap:wrap}.eventform>.primary{grid-column:1/-1}.controlbar{flex-wrap:wrap}.controlbar button{white-space:nowrap}.eventform{gap:6px}.event-clock-box{padding:5px 0}.subform{grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto auto;min-height:48px}.sub-clock-inline{display:flex;align-items:center;gap:5px}.sub-clock-inline .event-clock{min-width:62px;height:34px;font-size:12px}.subform .smallbtn{white-space:nowrap}</style>`)}
function render(){ensureCustomStyles();app.innerHTML=`<div class="layout">${nav()}<main>${header()}${state.loading?'<section class="panel"><div class="empty">Carregando dados...</div></section>':content()}</main></div>`;bind();if(state.timerStartedAt)startTicker()}
async function openMatchFromButton(id){
  try{
    if(!id){ toast('ID da partida não encontrado.','error'); return }
    const match = state.matches.find(m=>String(m.id)===String(id))
    if(match) state.selectedMatch={...match}
    state.tab='ao_vivo'
    const mr = match ? {data:match,error:null} : await supabase.from('matches').select('*').eq('id',id).maybeSingle()
    if(mr.error) throw mr.error
    if(!mr.data){ toast('Partida não encontrada.','error'); return }
    state.selectedMatch=mr.data
    const [ev,lu,v] = await Promise.all([
      supabase.from('match_events').select('*').eq('match_id',id).order('created_at',{ascending:true}),
      supabase.from('match_lineups').select('*').eq('match_id',id),
      supabase.from('match_votes').select('*').eq('match_id',id)
    ])
    if(ev.error) throw ev.error
    if(lu.error) throw lu.error
    if(v.error) throw v.error
    state.events=ev.data||[]
    state.lineups=lu.data||[]
    state.votes=v.data||[]
    render()
    window.scrollTo({top:0,behavior:'smooth'})
  }catch(err){
    console.error('Erro ao abrir partida:',err)
    toast('Não foi possível abrir a partida: '+(err?.message||'erro desconhecido'),'error')
  }
}

function bind(){document.querySelectorAll('[data-open-match]').forEach(b=>{b.type='button';b.onclick=async e=>{e.preventDefault();e.stopImmediatePropagation();await openMatchFromButton(b.dataset.openMatch)}});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.reportType=null;render()});document.querySelectorAll('[data-crud]').forEach(b=>b.onclick=()=>crudModal(b.dataset.crud));document.querySelectorAll('[data-edit-crud]').forEach(b=>b.onclick=()=>crudModal(b.dataset.editCrud,b.dataset.id));document.querySelectorAll('[data-delete-crud]').forEach(b=>b.onclick=()=>deleteCrud(b.dataset.deleteCrud,b.dataset.id));document.querySelectorAll('[data-save-crud]').forEach(b=>b.onclick=()=>saveCrud(b.dataset.saveCrud,b.dataset.id));document.querySelector('#authBtn')?.addEventListener('click',()=>state.session?openUserMenu():openAuth());document.querySelectorAll('[data-event-clock-adjust]').forEach(b=>b.onclick=()=>{adjustEventClock(Number(b.dataset.eventClockAdjust));render()});document.querySelectorAll('[data-event-timer]').forEach(b=>b.onclick=()=>{b.dataset.eventTimer==='reset'?resetEventTimer():toggleEventTimer()});document.querySelectorAll('[data-sub-edit]').forEach(b=>b.onclick=()=>editSub(b.dataset.subEdit));document.querySelectorAll('[data-sub-delete]').forEach(b=>b.onclick=()=>deleteSub(b.dataset.subDelete));document.querySelector('[data-sub-cancel]')?.addEventListener('click',()=>{state.editingSubId=null;render()});document.querySelector('#eventTeam')?.addEventListener('change',()=>{const sel=document.querySelector('#eventPlayer');const team=document.querySelector('#eventTeam')?.value;if(!sel)return;const ps=state.players.filter(p=>p.team_id===team).sort((a,b)=>(Number(a.shirt_number)||999)-(Number(b.shirt_number)||999));sel.innerHTML='<option value="">Atleta</option>'+ps.map(p=>`<option value="${p.id}">${p.shirt_number?`#${p.shirt_number} - `:''}${esc(p.full_name||p.name)} - ${esc(teamName(p.team_id))}</option>`).join('')});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a==='start1')await startHalf('1T');if(a==='start2')await startHalf('2T');if(a==='pause')await pause();if(a==='finish')await finishMatch();if(a==='event'){const ok=await askConfirm('Salvar esta ocorrência?');if(ok)await addEvent();}if(a==='sub')await addSub();if(a==='saveLineup')await saveLineup();if(a==='saveScoreCorrection')await saveScoreCorrection()});document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>vote(b.dataset.vote));document.querySelectorAll('[data-reopen-match]').forEach(b=>b.onclick=()=>reopenMatch(b.dataset.reopenMatch));document.querySelectorAll('[data-not-started]').forEach(b=>b.onclick=()=>markNotStarted(b.dataset.notStarted));document.querySelectorAll('[data-sponsor-new]').forEach(b=>b.onclick=()=>sponsorModal());document.querySelectorAll('[data-sponsor-edit]').forEach(b=>b.onclick=()=>sponsorModal(b.dataset.sponsorEdit));document.querySelectorAll('[data-sponsor-delete]').forEach(b=>b.onclick=()=>deleteSponsor(b.dataset.sponsorDelete));document.querySelectorAll('[data-media-new]').forEach(b=>b.onclick=()=>mediaModal());document.querySelectorAll('[data-media-delete]').forEach(b=>b.onclick=()=>deleteMedia(b.dataset.mediaDelete));document.querySelectorAll('[data-event-edit]').forEach(b=>b.onclick=async()=>{const ok=await askConfirm('Alterar este evento?');if(ok)eventEditModal(b.dataset.eventEdit)});document.querySelectorAll('[data-event-delete]').forEach(b=>b.onclick=async()=>{const ok=await askConfirm('Excluir este evento?');if(ok)deleteEvent(b.dataset.eventDelete)});document.querySelector('[data-occurrence-edit-last]')?.addEventListener('click',async()=>{const last=state.events.slice().reverse()[0];if(!last)return toast('Nenhuma ocorrência para alterar.','error');const ok=await askConfirm('Alterar a última ocorrência?');if(ok)eventEditModal(last.id)});document.querySelector('[data-occurrence-delete-last]')?.addEventListener('click',async()=>{const last=state.events.slice().reverse()[0];if(!last)return toast('Nenhuma ocorrência para excluir.','error');const ok=await askConfirm('Excluir a última ocorrência?');if(ok)await deleteEvent(last.id)});document.querySelectorAll('[data-event-update]').forEach(b=>b.onclick=()=>updateEvent(b.dataset.eventUpdate));document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{state.reportType=b.dataset.report;render()});document.querySelector('[data-print-report]')?.addEventListener('click',()=>window.print());document.querySelector('[data-sponsor-save]')?.addEventListener('click',e=>saveSponsor(e.target.dataset.sponsorSave||''));document.querySelector('[data-media-save]')?.addEventListener('click',saveMedia);document.querySelector('[data-configure-competition]')?.addEventListener('click',openCompetitionConfig);document.querySelectorAll('[data-lineup-status]').forEach(b=>b.onclick=()=>lineupStatusModal(b.dataset.lineupStatus));}

function openUserMenu(){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="userModal"><div class="modalbox"><button class="close" data-close>×</button><div class="eyebrow">USUÁRIO</div><h2>${esc(state.profile?.full_name||state.session.user.email)}</h2><p>Perfil: <b>${roleLabel(state.profile?.role)}</b></p><button class="danger wide" id="logoutBtn">Sair</button></div></div>`);document.querySelector('#logoutBtn').onclick=logout}
document.addEventListener('click',async e=>{const t=e.target.closest('button,a');if(!t)return;if(t.matches('[data-close]')){t.closest('.modal')?.remove();return}if(t.matches('[data-auth-submit]')){await authSubmit();return}if(t.matches('[data-sponsor-save]')){await saveSponsor(t.dataset.sponsorSave||'');return}if(t.matches('[data-media-save]')){await saveMedia();return}if(t.matches('[data-open-match]')){e.preventDefault();e.stopPropagation();await openMatchFromButton(t.dataset.openMatch);return}if(t.matches('[data-clock-adjust]')){await adjustClock(Number(t.dataset.clockAdjust)||0);return}if(t.matches('[data-phase-add]')){const list=document.querySelector('#phaseList');if(list)list.insertAdjacentHTML('beforeend',phaseRow({name:'',type:'classificatoria'},document.querySelectorAll('[data-phase-row]').length));return}if(t.matches('[data-phase-remove]')){t.closest('[data-phase-row]')?.remove();return}if(t.matches('[data-phase-save]')){await saveCompetitionConfig();return}if(t.matches('[data-lineup-status]')){lineupStatusModal(t.dataset.lineupStatus);return}if(t.matches('[data-lineup-choice]')){const id=t.dataset.lineupChoice,st=t.dataset.status,btn=document.querySelector(`[data-lineup-status="${id}"]`);if(btn){btn.dataset.status=st;btn.textContent=lineupStatusLabel(st);btn.className=`statusbtn status-${st}`}document.querySelector('#lineupStatusModal')?.remove();return}if(t.matches('[data-score-inc]')){await adjustScore(t.dataset.scoreInc,1);return}if(t.matches('[data-score-dec]')){await adjustScore(t.dataset.scoreDec,-1);return}if(t.matches('[data-minute-adjust]')){await adjustMinute(Number(t.dataset.minuteAdjust));return}if(t.matches('[data-classification]')){state.tab=t.dataset.classification==='grupo'?'grupos':'classificacao';render();return}if(t.matches('[data-toggle-auth]')){state.authMode=state.authMode==='login'?'signup':'login';document.querySelector('#authModal')?.remove();openAuth();return}})

supabase.auth.onAuthStateChange(async()=>{setTimeout(load,0)})
